# Remaining states: one bilingual helper registers Hindi (Y) and English (EN) together,
# so list lengths always match.
import data7
from data1 import Y
from en6 import EN, E
def B(slug, state, cat, icon, link, name, short, tag, ministry, facts, about, benefits, elig, notelig, docs, steps, ll, helpline, faq, note):
    h = lambda p: p[0]
    e = lambda p: p[1]
    Y.append(dict(slug=slug, state=state, name=h(name), short=h(short), cat=cat, icon=icon, tag=h(tag), ministry=h(ministry),
        facts=[(h(a), h(b)) for a, b in facts], about=h(about), benefits=[h(x) for x in benefits], elig=[h(x) for x in elig],
        notelig=[h(x) for x in notelig], docs=[h(x) for x in docs], steps=[h(x) for x in steps], link=(link, h(ll)),
        helpline=h(helpline), faq=[(h(q), h(a)) for q, a in faq], note=h(note)))
    E(slug, name=e(name), short=e(short), tag=e(tag), ministry=e(ministry), facts=[(e(a), e(b)) for a, b in facts], about=e(about),
      benefits=[e(x) for x in benefits], elig=[e(x) for x in elig], notelig=[e(x) for x in notelig], docs=[e(x) for x in docs],
      steps=[e(x) for x in steps], link_label=e(ll), helpline=e(helpline), faq=[(e(q), e(a)) for q, a in faq], note=e(note))

